summary_rows = value.get('summary') or []
interval_rows = value.get('interval') or []
events_rows = value.get('events') or []
asset_info = value.get('assetInfo') or {}

def first_present(row, keys):
    for key in keys:
        if key in row and row.get(key) not in [None, '']:
            return row.get(key)
    return None

def to_float(v):
    if v in [None, '']:
        return None
    try:
        return float(v)
    except Exception:
        return None

def get_colors(a, p, q, oee):
    default = {
        'oeeColor': '#d5d5d5',
        'availabilityColor': '#d5d5d5',
        'performanceColor': '#d5d5d5',
        'qualityColor': '#d5d5d5'
    }
    asset_path = asset_info.get('assetPath')
    if not asset_path or a is None or p is None or q is None or oee is None:
        return default
    try:
        colors = system.kanoa.event.getOEEColors({'assetPath': asset_path}, oee, a, min(p, 1.0), q)
        return {
            'oeeColor': colors.get('oee') or '#d5d5d5',
            'availabilityColor': colors.get('availability') or '#d5d5d5',
            'performanceColor': colors.get('performance') or '#d5d5d5',
            'qualityColor': colors.get('quality') or '#d5d5d5'
        }
    except Exception:
        return default

def build_row(source, rows):
    result = {
        'source': source,
        'returnedRowCount': len(rows),
        'oee': None,
        'availability': None,
        'performance': None,
        'quality': None,
        'oeeColor': '#d5d5d5',
        'availabilityColor': '#d5d5d5',
        'performanceColor': '#d5d5d5',
        'qualityColor': '#d5d5d5'
    }

    if len(rows) == 0:
        return result

    dict_rows = [r for r in rows if hasattr(r, 'get')]
    if len(dict_rows) == 0:
        return result

    first = dict_rows[0]
    if first.get('error') not in [None, '']:
        return result

    result['availability'] = first_present(first, ['availability', 'availabilityRatio'])
    result['performance'] = first_present(first, ['performance', 'performanceRatio'])
    result['quality'] = first_present(first, ['quality', 'qualityRatio'])

    a = to_float(result['availability'])
    p = to_float(result['performance'])
    q = to_float(result['quality'])
    if a is not None and p is not None and q is not None:
        result['oee'] = a * min(p, 1.0) * q

    result.update(get_colors(a, p, q, result['oee']))
    return result

return [
    build_row('getOEESummary()', summary_rows),
    build_row('getOEEDataByInterval()', interval_rows),
    build_row('getAssetProductionEvents()', events_rows)
]


